 const content=rs.map((x,j)=>{if(x.status!=="fulfilled"||x.value.exit_code!==0)throw new Error("read "+j);return x.value.output;}).join("");
 if(content.length!==row.pin.bytes)throw new Error("length");
 store("native_failure_metadata_active",{row,stage:"before_POST"});
 const post=await tools.mcp__codex_apps__github_create_blob({repository_full_name:"TrillionniumFoundation/Hepta",encoding:"utf-8",content});
 store("native_failure_metadata_active",{row,content,post,stage:"POST_returned"});
 if(post.structuredContent?.sha!==row.pin.git_blob)throw new Error("POST "+name);
